CREATE TABLE layout_document (id INTEGER PRIMARY KEY CHECK (id=1), schema TEXT NOT NULL, name TEXT NOT NULL, print_target TEXT);
CREATE TABLE layout_scalar64 (id INTEGER PRIMARY KEY, value REAL, value_ieee754_bits INTEGER NOT NULL, value_numeric_class TEXT NOT NULL);
CREATE TABLE layout_scalar32 (id INTEGER PRIMARY KEY, value REAL, value_ieee754_bits INTEGER NOT NULL, value_numeric_class TEXT NOT NULL);
CREATE TABLE layout_color (id INTEGER PRIMARY KEY, r_id INTEGER NOT NULL REFERENCES layout_scalar32(id), g_id INTEGER NOT NULL REFERENCES layout_scalar32(id), b_id INTEGER NOT NULL REFERENCES layout_scalar32(id), a_id INTEGER NOT NULL REFERENCES layout_scalar32(id));
CREATE TABLE layout_rect (id INTEGER PRIMARY KEY, x_id INTEGER NOT NULL REFERENCES layout_scalar64(id), y_id INTEGER NOT NULL REFERENCES layout_scalar64(id), width_id INTEGER NOT NULL REFERENCES layout_scalar64(id), height_id INTEGER NOT NULL REFERENCES layout_scalar64(id));
CREATE TABLE layout_bounds (id INTEGER PRIMARY KEY, x_id INTEGER NOT NULL REFERENCES layout_scalar64(id), y_id INTEGER NOT NULL REFERENCES layout_scalar64(id), width_id INTEGER NOT NULL REFERENCES layout_scalar64(id), height_id INTEGER NOT NULL REFERENCES layout_scalar64(id), rotation_id INTEGER NOT NULL REFERENCES layout_scalar64(id));
CREATE TABLE layout_grid (id INTEGER PRIMARY KEY REFERENCES layout_document(id), baseline_grid_id INTEGER NOT NULL REFERENCES layout_scalar64(id), baseline_offset_id INTEGER NOT NULL REFERENCES layout_scalar64(id), snap_to_baseline INTEGER NOT NULL CHECK (snap_to_baseline IN (0,1)));
CREATE TABLE layout_paragraph_style (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES layout_document(id), ordinal INTEGER NOT NULL, native_id TEXT NOT NULL, name TEXT NOT NULL, font_family TEXT NOT NULL, font_size_id INTEGER NOT NULL REFERENCES layout_scalar64(id), font_weight INTEGER NOT NULL CHECK (font_weight BETWEEN 0 AND 4294967295), leading_id INTEGER NOT NULL REFERENCES layout_scalar64(id), tracking_id INTEGER NOT NULL REFERENCES layout_scalar64(id), alignment TEXT NOT NULL);
CREATE TABLE layout_character_style (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES layout_document(id), ordinal INTEGER NOT NULL, native_id TEXT NOT NULL, name TEXT, font_family TEXT, font_size_id INTEGER REFERENCES layout_scalar64(id), font_weight INTEGER CHECK (font_weight BETWEEN 0 AND 4294967295), italic INTEGER CHECK (italic IN (0,1)), color_id INTEGER REFERENCES layout_color(id), tracking_id INTEGER REFERENCES layout_scalar64(id));
CREATE TABLE layout_story (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES layout_document(id), ordinal INTEGER NOT NULL, native_id TEXT NOT NULL, content TEXT NOT NULL);
CREATE TABLE layout_style_run (id INTEGER PRIMARY KEY, story_id INTEGER NOT NULL REFERENCES layout_story(id), ordinal INTEGER NOT NULL, start_hi INTEGER NOT NULL CHECK (start_hi BETWEEN 0 AND 4294967295), start_lo INTEGER NOT NULL CHECK (start_lo BETWEEN 0 AND 4294967295), end_hi INTEGER NOT NULL CHECK (end_hi BETWEEN 0 AND 4294967295), end_lo INTEGER NOT NULL CHECK (end_lo BETWEEN 0 AND 4294967295), paragraph_style_id TEXT, character_style_id TEXT);
CREATE TABLE layout_image_link (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES layout_document(id), ordinal INTEGER NOT NULL, native_id TEXT NOT NULL, path TEXT NOT NULL, hash TEXT NOT NULL, width INTEGER NOT NULL CHECK (width BETWEEN 0 AND 4294967295), height INTEGER NOT NULL CHECK (height BETWEEN 0 AND 4294967295), dpi INTEGER NOT NULL CHECK (dpi BETWEEN 0 AND 4294967295), color_profile TEXT, state TEXT, proxy_data_url TEXT, artifact_kind TEXT NOT NULL, artifact_ref TEXT NOT NULL);
CREATE TABLE layout_parent_page (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES layout_document(id), ordinal INTEGER NOT NULL, native_id TEXT NOT NULL, name TEXT NOT NULL, width_id INTEGER NOT NULL REFERENCES layout_scalar64(id), height_id INTEGER NOT NULL REFERENCES layout_scalar64(id));
CREATE TABLE layout_page (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES layout_document(id), ordinal INTEGER NOT NULL, native_id TEXT NOT NULL, name TEXT NOT NULL, spread_id TEXT NOT NULL, parent_page_id TEXT, width_id INTEGER NOT NULL REFERENCES layout_scalar64(id), height_id INTEGER NOT NULL REFERENCES layout_scalar64(id));
CREATE TABLE layout_parent_layer_id (id INTEGER PRIMARY KEY, parent_id INTEGER NOT NULL REFERENCES layout_parent_page(id), ordinal INTEGER NOT NULL, native_id TEXT NOT NULL);
CREATE TABLE layout_page_layer_id (id INTEGER PRIMARY KEY, page_id INTEGER NOT NULL REFERENCES layout_page(id), ordinal INTEGER NOT NULL, native_id TEXT NOT NULL);
CREATE TABLE layout_layer (id INTEGER PRIMARY KEY, page_id INTEGER REFERENCES layout_page(id), parent_id INTEGER REFERENCES layout_parent_page(id), ordinal INTEGER NOT NULL, native_id TEXT NOT NULL, name TEXT NOT NULL, visible INTEGER NOT NULL CHECK (visible IN (0,1)), locked INTEGER NOT NULL CHECK (locked IN (0,1)), CHECK ((page_id IS NULL) <> (parent_id IS NULL)));
CREATE TABLE layout_layer_object (id INTEGER PRIMARY KEY, layer_id INTEGER NOT NULL REFERENCES layout_layer(id), ordinal INTEGER NOT NULL, native_id TEXT NOT NULL);
CREATE TABLE layout_frame (id INTEGER PRIMARY KEY, page_id INTEGER REFERENCES layout_page(id), parent_id INTEGER REFERENCES layout_parent_page(id), ordinal INTEGER NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('rect','text','image')), native_id TEXT NOT NULL, layer_id TEXT NOT NULL, bounds_id INTEGER NOT NULL REFERENCES layout_bounds(id), locked INTEGER CHECK (locked IN (0,1)), visible INTEGER CHECK (visible IN (0,1)), CHECK ((page_id IS NULL) <> (parent_id IS NULL)));
CREATE TABLE layout_frame_rect (id INTEGER PRIMARY KEY REFERENCES layout_frame(id), fill_id INTEGER REFERENCES layout_color(id), stroke_id INTEGER REFERENCES layout_color(id));
CREATE TABLE layout_frame_text (id INTEGER PRIMARY KEY REFERENCES layout_frame(id), story_id TEXT NOT NULL, thread_next TEXT, columns INTEGER NOT NULL CHECK (columns BETWEEN 0 AND 4294967295), inset_id INTEGER NOT NULL REFERENCES layout_rect(id), wrap_mode TEXT NOT NULL);
CREATE TABLE layout_frame_image (id INTEGER PRIMARY KEY REFERENCES layout_frame(id), link_id TEXT NOT NULL);
CREATE TABLE layout_page_margins (id INTEGER PRIMARY KEY REFERENCES layout_page(id), top_id INTEGER NOT NULL REFERENCES layout_scalar64(id), right_id INTEGER NOT NULL REFERENCES layout_scalar64(id), bottom_id INTEGER NOT NULL REFERENCES layout_scalar64(id), left_id INTEGER NOT NULL REFERENCES layout_scalar64(id));
CREATE TABLE layout_page_columns (id INTEGER PRIMARY KEY REFERENCES layout_page(id), count INTEGER NOT NULL CHECK (count BETWEEN 0 AND 4294967295), gutter_id INTEGER NOT NULL REFERENCES layout_scalar64(id));
CREATE TABLE layout_guide (id INTEGER PRIMARY KEY, page_id INTEGER NOT NULL REFERENCES layout_page(id), ordinal INTEGER NOT NULL, rect_id INTEGER NOT NULL REFERENCES layout_rect(id));
CREATE TABLE layout_override (id INTEGER PRIMARY KEY, page_id INTEGER NOT NULL REFERENCES layout_page(id), ordinal INTEGER NOT NULL, object_id TEXT NOT NULL, bounds_id INTEGER REFERENCES layout_bounds(id), visible INTEGER CHECK (visible IN (0,1)), locked INTEGER CHECK (locked IN (0,1)));
CREATE TABLE layout_spread (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES layout_document(id), ordinal INTEGER NOT NULL, native_id TEXT NOT NULL, name TEXT NOT NULL);
CREATE TABLE layout_spread_page (id INTEGER PRIMARY KEY, spread_id INTEGER NOT NULL REFERENCES layout_spread(id), ordinal INTEGER NOT NULL, native_id TEXT NOT NULL);
CREATE TABLE layout_drawing_component (id INTEGER PRIMARY KEY REFERENCES layout_document(id), child_id TEXT NOT NULL, artifact_kind TEXT NOT NULL, standard TEXT NOT NULL, subset TEXT NOT NULL, document_id TEXT NOT NULL, drawing_id INTEGER NOT NULL REFERENCES semio_drawing_document(id));
CREATE TABLE layout_model_link (id INTEGER PRIMARY KEY REFERENCES layout_document(id), artifact_kind TEXT NOT NULL, standard TEXT NOT NULL, subset TEXT NOT NULL, artifact_id TEXT NOT NULL, role TEXT NOT NULL, pin_kind TEXT NOT NULL CHECK (pin_kind IN ('head','checkpoint','snapshot')));
CREATE TABLE layout_model_checkpoint (id INTEGER PRIMARY KEY REFERENCES layout_model_link(id), checkpoint_id TEXT NOT NULL);
CREATE TABLE layout_model_snapshot (id INTEGER PRIMARY KEY REFERENCES layout_model_link(id), hash TEXT NOT NULL, size_hi INTEGER NOT NULL CHECK (size_hi BETWEEN 0 AND 4294967295), size_lo INTEGER NOT NULL CHECK (size_lo BETWEEN 0 AND 4294967295), media_type TEXT NOT NULL);
CREATE TABLE layout_form_dictionary (id INTEGER PRIMARY KEY CHECK (id=1), document_id INTEGER NOT NULL REFERENCES layout_document(id));
CREATE TABLE layout_dictionary_entry (id INTEGER PRIMARY KEY, dictionary_id INTEGER NOT NULL REFERENCES layout_form_dictionary(id), ordinal INTEGER NOT NULL CHECK (ordinal>=0), question_id TEXT NOT NULL, value_id INTEGER NOT NULL REFERENCES layout_dictionary_value(id));
CREATE TABLE layout_dictionary_value (id INTEGER PRIMARY KEY, kind TEXT NOT NULL CHECK (kind IN ('null','boolean','unsigned','signed','float','text','bytes','array','object')));
CREATE TABLE layout_dictionary_boolean (id INTEGER PRIMARY KEY REFERENCES layout_dictionary_value(id), value INTEGER NOT NULL CHECK (value IN (0,1)));
CREATE TABLE layout_dictionary_unsigned (id INTEGER PRIMARY KEY REFERENCES layout_dictionary_value(id), value TEXT NOT NULL);
CREATE TABLE layout_dictionary_signed (id INTEGER PRIMARY KEY REFERENCES layout_dictionary_value(id), value INTEGER NOT NULL);
CREATE TABLE layout_dictionary_float (id INTEGER PRIMARY KEY REFERENCES layout_dictionary_value(id), scalar_id INTEGER NOT NULL REFERENCES layout_scalar64(id));
CREATE TABLE layout_dictionary_text (id INTEGER PRIMARY KEY REFERENCES layout_dictionary_value(id), value TEXT NOT NULL);
CREATE TABLE layout_dictionary_bytes (id INTEGER PRIMARY KEY REFERENCES layout_dictionary_value(id), value BLOB NOT NULL);
CREATE TABLE layout_dictionary_array (id INTEGER PRIMARY KEY, parent_value_id INTEGER NOT NULL REFERENCES layout_dictionary_value(id), ordinal INTEGER NOT NULL CHECK (ordinal>=0), value_id INTEGER NOT NULL REFERENCES layout_dictionary_value(id));
CREATE TABLE layout_dictionary_member (id INTEGER PRIMARY KEY, parent_value_id INTEGER NOT NULL REFERENCES layout_dictionary_value(id), ordinal INTEGER NOT NULL CHECK (ordinal>=0), name TEXT NOT NULL, value_id INTEGER NOT NULL REFERENCES layout_dictionary_value(id));
